import sys
from collections import deque

def bfs(grid, start, end, h, w):
    queue = deque([start])
    visited = set([start])
    while queue:
        x, y = queue.popleft()
        if (x, y) == end:
            return True
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == '.' and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny))
    return False

h, w, q = map(int, sys.stdin.readline().split())
grid = [sys.stdin.readline().strip() for _ in range(h)]

for _ in range(q):
    k = int(sys.stdin.readline())
    temporarily_blocked = set(tuple(map(int, sys.stdin.readline().split())) for _ in range(k))
    temp_grid = [list(row) for row in grid]
    for ri, ci in temporarily_blocked:
        temp_grid[ri-1][ci-1] = '#'

    start = (0, 0)
    end = (h-1, w-1)
    if bfs(temp_grid, start, end, h, w):
        temp_grid[end[0]][end[1]] = '.'
        if bfs(temp_grid, end, start, h, w):
            print("YES")
        else:
            print("NO")
    else:
        print("NO")
    sys.stdout.flush()
